# where shift = 1 if c < r else 0

def corrected_formula(r, c):
    # For rows 0-16:
    # base = 2, shift = 1 if c < r else 0
    return wrap_mod9(c + 2 + (1 if c < r else 0))

print("Testing corrected formula for rows 0-16:")

matches = 0
total_nonzero = 0
errors = []

for r in range(0, 17):
    for c in range(23):
        if grid[r][c] != 0:
            total_nonzero += 1
            expected = corrected_formula(r, c)
            actual = grid[r][c]
            if expected == actual:
                matches += 1
            else:
                errors.append(((r, c), expected, actual))

print(f"Corrected formula matches: {matches}/{total_nonzero} non-zero cells in rows 0-16")

if errors:
    print("Errors:")
    for ((r, c), exp, act) in errors:
        print(f"Row {r}, col {c}: expected {exp}, actual {act}")

# Now I need to verify that the corrected formula handles the zero cells properly
# And also complete the bottom pattern for columns 16+ in rows 9-16

print("\n\nNow let me analyze cols 16-22 in rows 9-16 more carefully:")
for r in range(9, 17):
    row = grid[r]
    row_str = f"Row {r}: "
    for c in range(16, 23):
        v = row[c] if row[c] != 0 else '?'
        row_str += f"col {c-16}={v} "
