# base=3 for cols 0-15:
print("\n\nChecking rows 15-16, cols 0-15 with base=3 formula:")
for r in range(15, 17):
    print(f"Row {r} cols 0-15:")
    for c in range(16):
        exp = wrap_mod9(c + 3)
        act = grid[r][c]
        if act != 0:
            match = "✓" if exp == act else "?"
            print(f"  c={c}: exp={exp}, act={act} {match}")
        else:
            print(f"  c={c}: exp={exp} (MISSING)")
    print()

# Now let me build the complete grid with filled zeros

W, H = 23, 23
new_grid = [[0] * W for _ in range(H)]

for r in range(H):
    for c in range(W):
        if grid[r][c] != 0:
            new_grid[r][c] = grid[r][c]
        else:
            # Fill based on region
            if r >= 17:
                # Bottom region: wrap_mod9(c + 3) for all cols
                # Then apply shift for cols 16-22 if c >= r
                base_val = wrap_mod9(c + 3)
                if c >= r:
                    base_val = (base_val - 1) if base_val > 1 else 9
                new_grid[r][c] = base_val
            elif r >= 15:
                # Transition rows 15-16
                # Cols 0-15: correct_formula
                # Cols 16-22: bottom_formula
                if c < 16:
                    new_grid[r][c] = corrected_formula(r, c)
                else:
                    base_val = wrap_mod9(c + 3)
                    if c >= r:
                        base_val = (base_val - 1) if base_val > 1 else 9
                    new_grid[r][c] = base_val
            else:
                # Rows 0-14: correct_formula
                new_grid[r][c] = corrected_formula(r, c)

print("Filled grid (as string):")
for row in new_grid:
    print(' '.join(map(str, row)))

